import{_ as t,o,c as l,a4 as n,j as e,a as s}from"./chunks/framework.CQGI5ZO3.js";const D=JSON.parse('{"title":"xs-install(1)","description":"Install locally, build static release binaries, and put the helper on the machines you sync with.","frontmatter":{"title":"xs-install(1)","description":"Install locally, build static release binaries, and put the helper on the machines you sync with.","manual":"xs-install(1)","manualName":"Install & releases","sectionNumber":"1"},"headers":[],"relativePath":"install.md","filePath":"install.md"}'),r={name:"install.md"};function i(c,a,d,p,h,E){return o(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="xs-install-1" tabindex="-1">xs-install(1) <a class="header-anchor" href="#xs-install-1" aria-label="Permalink to &quot;xs-install(1)&quot;">​</a></h1><div class="manual-deck"><strong>Install &amp; releases</strong><p>Install locally, build static release binaries, and put the helper on the machines you sync with.</p></div><h2 id="local" tabindex="-1">LOCAL INSTALL <a class="header-anchor" href="#local" aria-label="Permalink to &quot;LOCAL INSTALL {#local}&quot;">​</a></h2><div class="example-caption">From a built checkout (see <a href="getting-started.html#build">getting started</a>)</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> build</span><span style="color:#DEDEDE;"> --prefix</span><span style="color:#DEDEDE;"> &quot;$HOME/.local&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">export PATH=</span><span style="color:#DEDEDE;">&quot;$HOME/.local/bin:$PATH&quot;</span></span></code></pre></div><p>This installs <code>xs</code>, a manpage generated from its own <code>--help</code>, and zsh completion. The completion builds on zsh’s rsync completion. For zsh, add <code>fpath=(&quot;$HOME/.local/share/zsh/site-functions&quot; $fpath)</code> before <code>compinit</code> in <code>.zshrc</code>. Release binaries already in <code>dist/</code> are installed too, under <code>share/xs/releases/</code>, for <a href="#remote">remote install</a>.</p><h2 id="homebrew" tabindex="-1">HOMEBREW (LOCAL TAP) <a class="header-anchor" href="#homebrew" aria-label="Permalink to &quot;HOMEBREW (LOCAL TAP) {#homebrew}&quot;">​</a></h2><div class="example-caption">A formula for this checkout, in a tap on your machine</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">python3 </span><span style="color:#DEDEDE;">tools/package.py</span></span>
<span class="line"><span style="color:#DEDEDE;">brew </span><span style="color:#DEDEDE;">tap-new</span><span style="color:#DEDEDE;"> xs/local</span></span>
<span class="line"><span style="color:#DEDEDE;">cp </span><span style="color:#DEDEDE;">dist/homebrew/Formula/xs.rb</span><span style="color:#DEDEDE;"> &quot;$(brew --repository xs/local)/Formula/&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">brew </span><span style="color:#DEDEDE;">install</span><span style="color:#DEDEDE;"> --build-from-source</span><span style="color:#DEDEDE;"> xs/local/xs</span></span>
<span class="line"><span style="color:#DEDEDE;">brew </span><span style="color:#DEDEDE;">test</span><span style="color:#DEDEDE;"> xs/local/xs</span></span></code></pre></div><p>The formula points at a source archive of this checkout and builds the vendored, hash-checked dependencies. No public tap is published. If the tap already exists, skip <code>tap-new</code>, and use <code>brew reinstall</code> to replace an installed copy.</p><h2 id="releases" tabindex="-1">RELEASE BINARIES <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;RELEASE BINARIES {#releases}&quot;">​</a></h2><div class="example-caption">Static binaries for every supported target</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--preset</span><span style="color:#DEDEDE;"> release-static</span></span>
<span class="line"><span style="color:#DEDEDE;">cmake </span><span style="color:#DEDEDE;">--build</span><span style="color:#DEDEDE;"> --preset</span><span style="color:#DEDEDE;"> release-static</span></span></code></pre></div><div class="manual-table-wrap"><table><thead><tr><th scope="col">Output</th><th scope="col">Target</th><th scope="col">Links against</th></tr></thead><tbody><tr><td><code>dist/xs-linux-amd64</code></td><td>Linux x86-64</td><td>nothing: fully static, built with musl</td></tr><tr><td><code>dist/xs-linux-arm64</code></td><td>Linux ARM64, such as a Raspberry Pi 4 or 5 on a 64-bit OS</td><td>nothing: fully static, built with musl</td></tr><tr><td><code>dist/xs-darwin-universal</code></td><td>macOS on Apple silicon and Intel</td><td>Apple system libraries only</td></tr><tr><td><code>dist/manifest.json</code></td><td colspan="2">SHA-256 of each binary</td></tr></tbody></table></div><p>The preset needs CMake 3.24+, Ninja, a C/C++ compiler, GNU make and Docker with Linux amd64/arm64 emulation. A Linux host can build the two Linux binaries; the macOS binary needs a macOS host. zstd, xxHash and ICU are vendored as hash-checked source archives. <code>xs --version</code> includes the source revision, with <code>-dirty</code> for modified sources. No binaries are published for download yet.</p><div class="example-caption">Check a binary against the manifest</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">python3 </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &quot;import json; print(json.load(open(&#39;dist/manifest.json&#39;))[&#39;xs-linux-arm64&#39;][&#39;sha256&#39;])&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">shasum </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> 256</span><span style="color:#DEDEDE;"> dist/xs-linux-arm64</span></span></code></pre></div><h2 id="remote" tabindex="-1">REMOTE INSTALL <a class="header-anchor" href="#remote" aria-label="Permalink to &quot;REMOTE INSTALL {#remote}&quot;">​</a></h2><p>Native transfers need <code>xs</code> on both machines. <code>--install</code> is the only way xs ever puts an executable on another host: transfers never upload one. It runs <code>uname</code> on the host over ssh, picks the matching release binary, and installs it atomically at <code>~/.local/bin/xs</code>.</p><div class="example-caption">Install xs on a host that does not have it, then push natively</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">export XSYNC_RELEASE_DIR=releases</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--install</span><span style="color:#DEDEDE;"> user@pi</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azi</span><span style="color:#DEDEDE;"> --no-fallback</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@pi:backup/</span><span style="color:#DEDEDE;"> | tail </span><span style="color:#DEDEDE;">-n</span><span style="color:#DEDEDE;"> 3</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>Installed xs-linux-amd64 on user@pi at ~/.local/bin/xs
xs  version 0.1.0  protocol version 4  git 1fff2a09ae2c
&lt;f+++++++++ notes.txt
cd+++++++++ scripts/
&lt;f+++++++++ scripts/build.sh</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><ul><li>It refuses to replace a newer or unrecognized <code>xs</code> unless <code>--force</code> is given. An interrupted or invalid upload leaves the previous executable in place.</li><li>Release binaries are looked for beside the local <code>xs</code>, then in a sibling <code>dist/</code>, then in <code>../share/xs/releases/</code>. <code>XSYNC_RELEASE_DIR</code> names another directory.</li><li>After installing, transfers find the helper in <code>~/.local/bin</code> even though it is not on the remote <code>PATH</code>, as the push above shows.</li></ul><h2 id="lookup" tabindex="-1">HOW TRANSFERS FIND THE HELPER <a class="header-anchor" href="#lookup" aria-label="Permalink to &quot;HOW TRANSFERS FIND THE HELPER {#lookup}&quot;">​</a></h2>`,24),e("figure",{class:"diagram"},[e("svg",{viewBox:"0 0 760 200",role:"img","aria-labelledby":"lookup-title lookup-desc"},[e("title",{id:"lookup-title"},"Remote helper lookup"),e("desc",{id:"lookup-desc"},"With --rsync-path the named command is used. Otherwise the remote shell tries xs on PATH, then ~/.local/bin/xs, then XSYNC_REMOTE_PATH; if none exists, the transfer falls back to rsync or exits 127."),e("defs",null,[e("marker",{id:"arrow-lookup",viewBox:"0 0 10 10",refX:"9",refY:"5",markerWidth:"7",markerHeight:"7",orient:"auto"},[e("path",{d:"M0,0 L10,5 L0,10 z",class:"diagram-arrowhead"})])]),e("rect",{x:"10",y:"20",width:"150",height:"56",rx:"3",class:"diagram-strong"}),e("text",{x:"85",y:"44","text-anchor":"middle",class:"diagram-title"},"--rsync-path?"),e("text",{x:"85",y:"62","text-anchor":"middle",class:"diagram-note"},"yes: run that command"),e("rect",{x:"200",y:"20",width:"120",height:"56",rx:"3"}),e("text",{x:"260",y:"44","text-anchor":"middle"},"xs on PATH"),e("text",{x:"260",y:"62","text-anchor":"middle",class:"diagram-note"},"remote PATH"),e("rect",{x:"360",y:"20",width:"140",height:"56",rx:"3"}),e("text",{x:"430",y:"44","text-anchor":"middle"},"~/.local/bin/xs"),e("text",{x:"430",y:"62","text-anchor":"middle",class:"diagram-note"},"where --install puts it"),e("rect",{x:"540",y:"20",width:"210",height:"56",rx:"3"}),e("text",{x:"645",y:"44","text-anchor":"middle"},"XSYNC_REMOTE_PATH"),e("text",{x:"645",y:"62","text-anchor":"middle",class:"diagram-note"},"local value first, then remote"),e("rect",{x:"430",y:"130",width:"320",height:"56",rx:"3",class:"diagram-strong"}),e("text",{x:"590",y:"154","text-anchor":"middle",class:"diagram-title"},"None found: shell exits 127"),e("text",{x:"590",y:"172","text-anchor":"middle",class:"diagram-note"},"fall back to rsync, or exit 127 with --no-fallback"),e("path",{d:"M160 48 L198 48","marker-end":"url(#arrow-lookup)"}),e("text",{x:"179",y:"40","text-anchor":"middle",class:"diagram-note"},"no"),e("path",{d:"M320 48 L358 48","marker-end":"url(#arrow-lookup)"}),e("path",{d:"M500 48 L538 48","marker-end":"url(#arrow-lookup)"}),e("path",{d:"M645 76 L645 128","marker-end":"url(#arrow-lookup)"})]),e("figcaption",null,[s("The first match runs as "),e("code",null,"xs --server"),s(". Each step is tried only if the previous one is not found.")])],-1),e("p",null,[e("code",null,"XSYNC_REMOTE_PATH"),s(" may contain spaces or start with "),e("code",null,"~/"),s(". An explicit "),e("code",null,"--rsync-path"),s(" is also used if the transfer falls back, so it must then accept rsync’s server arguments too; prefer the lookup when fallback matters.")],-1)])])}const x=t(r,[["render",i]]);export{D as __pageData,x as default};
